def browser_app(self, app, details):
    from .browser.security_warnings import detect_certificate_warning

    endpoint_results=[]
    certificate_warning_seen = False
    if app["app_id"] == "APP00006822":
        HTTPCheck().request({"url":app["urls"][0]["url"],"timeout":10})
    urls=app["urls"] if app.get("multi_endpoint")=="est" else [{"label":"Functional","url":app.get("functional_url",app["urls"][0]["url"])}]
    if app.get("availability"):
        for endpoint in app["urls"]:
            try:
                HTTPCheck().request({"url":endpoint["url"],"timeout":10})
                details.append({"step":"regional availability","endpoint":endpoint["label"],"status":"PASS"})
            except Exception:
                details.append({"step":"regional availability","endpoint":endpoint["label"],"status":"FAIL"})
    for endpoint in urls:
        driver=None; workflow=None; handler=None
        shared=app.get("session_scope")=="portal"
        warning_detail = None

        def record_warning(evidence):
            nonlocal certificate_warning_seen, warning_detail
            certificate_warning_seen = True
            if warning_detail is None:
                warning_detail = {
                    "step": "certificate",
                    "endpoint": endpoint["label"],
                    "status": "WARN",
                }
                details.append(warning_detail)
            warning_detail.update(evidence)

        def observe_warning():
            evidence = detect_certificate_warning(driver) if driver else None
            if evidence:
                record_warning(evidence)
            return evidence

        def stop_at_warning():
            if observe_warning():
                raise RuntimeError("NET-001: Browser certificate warning blocks checkout")

        try:
            driver=self.browser(app,shared)
            driver.set_page_load_timeout(app.get("page_load_timeout",30))
            workflow=BrowserWorkflow(driver,app,self.credentials,self.now().date(),timeout=app.get("action_timeout",10))
            if app["auth"]["strategy"]=="basic":
                values=self.credentials.get(app["auth"]["group"])
                from .browser.basic_auth import BasicAuthSession
                handler=BasicAuthSession(driver,endpoint["url"],app["auth"]["realm"],values)
            driver.get(endpoint["url"])
            evidence = observe_warning()
            proceed_links = []
            if app.get("allow_certificate_warning", False):
                proceed_links = driver.find_elements("css selector", "#proceed-link")
                if proceed_links:
                    if not evidence:
                        record_warning({
                            "reason": "Browser security warning encountered; cause not verified",
                        })
                    driver.execute_script("arguments[0].click();", proceed_links[0])
            if evidence and not proceed_links:
                raise RuntimeError("NET-001: Browser certificate warning blocks checkout")
            if shared:
                from selenium.common.exceptions import TimeoutException
                from selenium.webdriver.support.ui import WebDriverWait

                login_required = False

                # Portal itself always needs a definite ready-state decision.
                if app["app_id"] == "APP00005034":
                    workflow.wait.until(
                        lambda _: workflow.elements("login_user")
                        or "#!/employeeHome" in driver.current_url
                    )
                    login_required = bool(workflow.elements("login_user"))

                else:
                    # Portal Suite child apps may redirect to their own
                    # /login#!/credentials route after navigation. Give that
                    # redirect/login form time to appear before assuming the
                    # existing Portal session is already authenticated.
                    try:
                        WebDriverWait(driver, 5).until(
                            lambda _: workflow.elements("login_user")
                        )
                        login_required = True
                    except TimeoutException:
                        login_required = False

                if login_required:
                    from selenium.webdriver.support.ui import Select

                    Select(workflow.element("user_type")).select_by_value("emp")
                    workflow.login()

                    # Wait until authentication has moved away from credentials.
                    workflow.wait.until(
                        lambda _: "#!/credentials" not in driver.current_url
                    )

                    if app["app_id"] != "APP00005034":
                        driver.get(endpoint["url"])
                        stop_at_warning()

                if app["app_id"] == "APP00005034":
                    workflow.wait.until(
                        lambda _: "#!/employeeHome" in driver.current_url
                    )
                    workflow.element("portal_ready")
            else:
                workflow.execute(app.get("prelogin_steps",[]))
                workflow.login()
            workflow.execute()
            stop_at_warning()
            details.extend(workflow.details)
            endpoint_results.append("PASS")
            details.append({"step":"endpoint","endpoint":endpoint["label"],"status":"PASS"})
        except Exception as exc:
            blocked_by_warning = False
            try:
                blocked_by_warning = bool(observe_warning())
            except Exception:
                pass  # Preserve the original failure if inspection is unavailable.
            if blocked_by_warning:
                exc = RuntimeError("NET-001: Browser certificate warning blocks checkout")
            if workflow: details.extend(workflow.details)
            endpoint_results.append("FAIL")
            from .diagnostics import diagnostic,CODES
            code=diagnostic(exc)
            details.append({"step":"endpoint","endpoint":endpoint["label"],"status":"FAIL","reason":CODES[code],"diagnostic":code})
            if not app.get("multi_endpoint"):
                if blocked_by_warning:
                    raise exc from None
                raise
        finally:
            if driver and handler:
                try: handler.close()
                except Exception: pass
            if driver and not shared:
                try: driver.quit()
                except Exception: pass
    status = est_status(endpoint_results) if app.get("multi_endpoint") == "est" else "PASS"

    if any(
        d.get("step") == "regional availability" and d["status"] == "FAIL"
        for d in details
    ):
        status = "FAIL"

    if status == "PASS" and certificate_warning_seen:
        status = "WARN"

    if status == "PASS":
        message = "Functional checkout completed"
    elif status == "WARN":
        if any(result != "PASS" for result in endpoint_results):
            message = "Endpoint checks partially passed; inspect endpoint details"
            if certificate_warning_seen:
                message += "; browser security warning also encountered"
        else:
            message = "Functional checkout passed with browser security warning; cause not verified"
    else:
        message = "Endpoint checks include failures"

    diagnostic_code = None
    if status == "FAIL":
        diagnostic_code = next(
            (d["diagnostic"] for d in details if d.get("diagnostic")),
            "NET-001",
        )

    return self.result(
        app,
        status,
        message,
        details=details,
        diagnostic_code=diagnostic_code,
    )
